"""Generate the declared S1 closeout from saved evidence; never starts solvers."""
from pathlib import Path
from statistics import median
from collections import defaultdict
import json,hashlib,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'artifacts/s1_closeout';PROFILE=OUT/'profile'
load=lambda p:json.loads(p.read_text());save=lambda p,x:p.write_text(json.dumps(x,indent=2)+'\n')
allrows=[];groups=[];stats=[]
for size in (14,500):
 rows=[load(p) for p in sorted((PROFILE/str(size)/'attempts').glob('*.json'))];allrows+=rows
 audit=load(PROFILE/str(size)/'independent_audit.json');assert audit['states_replayed']==len(rows) and audit['discrepancies']==0
 primary=[r for r in rows if r['tags']['stage']!='warmup' and not r['tags'].get('retry')];assert len(primary)==48
 for stage in ('design','frozen'):
  for family in ('droop','droop_tap','droop_shunt','droop_tap_shunt'):
   for factor in (.9,1.):
    for solver in ('ipopt','madnlp','ccopt'):
     found=[r for r in rows if r['tags'].get('stage')==stage and r['tags'].get('family')==family and r['tags'].get('factor')==factor and r['solver']==solver]
     assert any(r['accepted'] for r in found),(size,stage,family,factor,solver)
     groups.append(dict(size=size,stage=stage,family=family,factor=factor,solver=solver,attempts=[r['name'] for r in found],accepted=True))
 for stage in ('design','frozen'):
  for solver in ('ipopt','madnlp','ccopt'):
   rs=[r for r in primary if r['tags']['stage']==stage and r['solver']==solver]
   stats.append(dict(size=size,stage=stage,solver=solver,direct_passes=sum(r['accepted'] for r in rs),direct_attempts=len(rs),median_build_seconds=median(r['build_seconds'] for r in rs),median_solve_seconds=median(r['solve_wall_seconds'] for r in rs),median_extraction_seconds=median(r['extraction_seconds'] for r in rs),median_validation_packaging_seconds=median(r['validation_and_packaging_seconds'] for r in rs),median_julia_allocated_mib=median(r['julia_allocated_bytes']/2**20 for r in rs),process_highwater_rss_gib=max(r['process_highwater_rss_bytes']/2**30 for r in rs),variables_min=min(r['variables'] for r in rs),variables_max=max(r['variables'] for r in rs),constraints_min=min(r['constraints'] for r in rs),constraints_max=max(r['constraints'] for r in rs)))
save(OUT/'profile_summary.json',dict(groups=groups,statistics=stats,environment=load(PROFILE/'environment.json')))
# Compact standalone SVG chart: measured primary attempts, failures included.
w,h=1150,530;plot=[];colors=['#286b9c','#be6b28'];esc=html.escape
plot+=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">','<rect width="100%" height="100%" fill="white"/>','<style>text{font-family:Arial,sans-serif;fill:#172b3a;font-size:13px}.title{font-size:20px;font-weight:bold}</style>','<text x="24" y="30" class="title">S1 serial known-witness profile</text>','<text x="24" y="53">Median of primary attempts; failed attempts included. Build may include first design specialization.</text>']
metrics=[('median_solve_seconds','Solve time (seconds)'),('median_julia_allocated_mib','Julia allocations (MiB)')]
for panel,(key,title) in enumerate(metrics):
 x0=60+panel*565;y0=100;pw=470;ph=310;maximum=max(r[key] for r in stats)*1.05
 plot.append(f'<text x="{x0}" y="{y0-14}">{esc(title)}</text>')
 for j in range(5):
  v=maximum*j/4;y=y0+ph*(1-j/4);plot +=[f'<line x1="{x0}" x2="{x0+pw}" y1="{y}" y2="{y}" stroke="#d9e1e7"/>',f'<text x="{x0-5}" y="{y+4}" text-anchor="end">{v:.1f}</text>']
 for i,(stage,solver) in enumerate((st,sol) for st in ('design','frozen') for sol in ('ipopt','madnlp','ccopt')):
  xx=x0+i*pw/6+7
  for j,size in enumerate((14,500)):
   r=next(r for r in stats if r['size']==size and r['stage']==stage and r['solver']==solver);bh=r[key]/maximum*ph
   plot.append(f'<rect x="{xx+j*24}" y="{y0+ph-bh}" width="22" height="{bh}" fill="{colors[j]}"/>')
  plot.append(f'<text x="{xx+22}" y="{y0+ph+18}" text-anchor="middle">{solver}</text>')
  if i in (1,4):plot.append(f'<text x="{xx+22}" y="{y0+ph+38}" text-anchor="middle">{stage}</text>')
plot+=['<rect x="30" y="480" width="18" height="12" fill="#286b9c"/><text x="55" y="491">14 buses</text>','<rect x="170" y="480" width="18" height="12" fill="#be6b28"/><text x="195" y="491">500 buses</text>','<text x="30" y="518">Allocations exclude native solver memory. Process RSS high-water is reported separately with its scope.</text>','</svg>']
(OUT/'profile.svg').write_text('\n'.join(plot))
env=load(PROFILE/'environment.json');lines=['# S1 closeout — 14 and 500 buses','','**Status: closed for the declared study, 2026-10-15.** This decision supersedes the previous network sequence and acceptance matrices.','','## Accepted scope','','ARPA-E Challenge 1 Network Model 01, scenarios 01 and 02; base-case steady-state AC optimization; Pmin=0 and symmetric Q limits; OPF-anchor initializations; zero deadband; independent 2–8% full-Q-span droop slopes and reference movement within ±0.02 pu where selected; source-relative ±5% tap bounds; continuous bank-specific susceptance bounds. The retained uniform 8% calibrated cases remain the reproducible baseline. The source generator limits and imported OPF/SCOPF results remain available separately.','','Five demands (90/95/100/105/110%) and all eight fixed/free control families are covered by the fixed-curve equipment and free-droop campaigns. Design-at-each-demand and one nominal design frozen across demands are different comparisons. Native termination, physical feasibility, local objective and control-policy bounds have separate outcomes.','','## Exit gates','','| Gate | Outcome |','|---|---|','| Formulation and independent physical validation | Retained equation/derivative coverage; all saved campaign states replayed independently |','| Control families, demand and initialization | Fixed/equipment and free-droop/frozen matrices complete at both sizes; three OPF anchors and three solvers |','| Numerical failure classification | Direct failures retained; same-model solver recoveries and changed-equipment fixes explicitly labelled |','| Scale and performance | Serial closeout profile: 96 primary combinations plus six backend warmups and six bounded retries; all combinations accepted after recovery |','| Reproducibility | Serialized cases, angle policies, device thresholds, witnesses, code/environment hashes, reports and provenance transition retained |','| Test hierarchy | Core vs extended numerical coverage classified; default package/CI gate retains both |','','## Numerical evidence','','| Campaign | Direct acceptance | Accepted combinations after recovery |','|---|---:|---:|','| 14-bus new free-droop design/frozen matrix | 360/360 | 120/120 solver/model/demand combinations |','| 500-bus new free-droop design/frozen matrix | 308/360 | 120/120 solver/model/demand combinations |','| Additional 14-bus tap/shunt-only comparators | 90/90 | 30/30 solver/model/demand combinations |','| 14-bus serial known-witness profile | 48/48 | 48/48 |','| 500-bus serial known-witness profile | 42/48 | 48/48 |','','The original 14-bus fixed-design direct score remains 42/45; its three CCOpt failures recovered separately with the original equality-bound equipment representation. Original direct scores are never overwritten by retries.','','The serial profile starts each cell from a previously independently accepted point for that same solver/model. It measures known-witness reproducibility and practical resource use; it is not an unseen-start success rate or a solver speed ranking. All numerical work ran in one Julia process, without a concurrent optimization process. Ordinary desktop and report/file activity continued. Each backend/size has a separate unscored nominal frozen warmup; first design build specializations can still include compilation. The 500-bus measurements follow all 14-bus design/frozen paths.','','The predeclared profile policy uses the primary campaign budgets (14:600 iterations/20 native solver seconds;500:1000/60). CCOpt starts with barrier 1e-6 and bound push/fraction 1e-8. At most one same-point retry is allowed, using 3000 iterations/120 seconds; CCOpt barrier 1e-8, or smooth solver bounds normalization. Thus 500-bus solver limits sum to at most 180 seconds for two attempts; model building and validation are measured separately. Existing broader stress experiments retain their own settings.','','The six first-attempt profile failures were all 500-bus CCOpt: design/shunts at 90%, design/taps+shunts at 100%, and all four frozen candidate families at 90%. Each recovered on its one conditioned retry. No operating limits, physical tolerances, objective or equipment equations changed.','','## Measured resources','','Hardware: '+str(env['cpu'])+'; Julia '+env['julia']+'; '+str(env['julia_threads'])+' Julia thread(s); '+str(env['cpu_threads'])+' logical CPU threads. Solver versions: '+str(env['solver_versions'])+'.','','| Buses | Stage | Solver | Direct | Median build s | Median solve s | Median extraction s | Median validation/packaging s | Julia allocation MiB | JuMP variables | JuMP constraints |','|---:|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in stats:lines.append(f"| {r['size']} | {r['stage']} | {r['solver']} | {r['direct_passes']}/{r['direct_attempts']} | {r['median_build_seconds']:.4f} | {r['median_solve_seconds']:.4f} | {r['median_extraction_seconds']:.4f} | {r['median_validation_packaging_seconds']:.4f} | {r['median_julia_allocated_mib']:.2f} | {r['variables_min']}–{r['variables_max']} | {r['constraints_min']}–{r['constraints_max']} |")
lines+=['','The table includes all primary attempts, including failures. Julia allocations cover optimizer construction/solve/extraction and exclude native allocations and subsequent validation/report packaging. RSS is a whole-process high-water mark, including startup/JIT and previous cells; it is not a per-model incremental peak. Maximum recorded process high-water: '+f"{max(r['process_highwater_rss_gib'] for r in stats):.3f} GiB"+'.','','![Serial profile](profile.svg)','','## Design decision and retained limitations','','At 90% demand the nominally designed frozen droop-only candidate changes loss from 0.645681 to 0.520776 MW at 14 buses, but from 33.072463 to 34.619274 MW at 500 buses. Keep the existing frozen 8% cases as the baseline. New solver-returned nominal curves are comparison candidates; nominal loss alone does not select the best shared controller across demands. Reference and slope change together in this extension.','','Restoring original Pmin is qualified at 500 buses. Frozen equipment with original Q or original P/Q limits remains unresolved; all ten changed-equipment contracts obtained Ipopt witnesses when taps and banks were freed. These are distinct physical policies and are not interchangeable recoveries. Final 14-bus original-limit qualification is also outside the accepted study scope. No global infeasibility certificate is claimed for local failures.','','The closeout does not establish continuous-demand robustness, global optimality, dynamics, discrete equipment feasibility or N-1 security. Those are future scopes. The supported evidence is the declared sampled steady-state envelope and bounded recovery workflow.','','## Cleanup and provenance','','Retired source networks, their study runners, reports, plots, exports and generated documentation were removed at the user’s request. Shared numerical helpers, generic solver APIs, small synthetic tests, and the retained source cases remain. `removal_manifest.json` contains only file paths, sizes and hashes; it is not an archive of the removed studies. `provenance_transition.json` records approved registry changes while preserving electrical inputs and saved-result hashes.','','## Evidence and regeneration','','Primary records: `artifacts/s1_arpae14_closeout/`, `artifacts/s1_arpae500/`, and `artifacts/s1_free_droop/`. The combined failed/recovered ledger remains under the free-droop directory. Profile attempts, model files, independent audits and environment metadata are under this closeout’s `profile/` directory. Test classification is in `test/README.md`.','','```sh','julia --project=. examples/s1_closeout_benchmark.jl','python3 examples/audit_s1_closeout.py','python3 examples/report_s1_closeout.py','julia --project=. test/runtests.jl','julia --project=docs docs/make.jl','```','']
validation=load(OUT/'validation.json') if (OUT/'validation.json').exists() else {}
if validation:
 lines+=['## Final verification','',f"Full retained regression suite: **{validation['full_regression']['passed']}/{validation['full_regression']['passed']} passed**, including core and extended coverage. Saved campaign replay: 856 points, zero discrepancies. New profile replay: 108 points, zero discrepancies. The cleanup audit checks retained network sizes and documentation file links. Documentation status is recorded in `validation.json`.",'']
text='\n'.join(lines);(OUT/'REPORT.md').write_text(text)
doc=text.replace('![Serial profile](profile.svg)','![Serial profile](assets/s1_closeout/profile.svg)')+'\nSee the [14-bus closeout](s1_14bus_closeout.md), [500-bus results](s1_500_results.md) and [free-droop results](s1_free_droop_results.md).\n'
(ROOT/'docs/src/s1_closeout.md').write_text(doc);assets=ROOT/'docs/src/assets/s1_closeout';assets.mkdir(exist_ok=True);(assets/'profile.svg').write_bytes((OUT/'profile.svg').read_bytes())
print('S1 closeout report generated; 96/96 profile combinations recovered')

